"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["16502"],{74562(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.etapa_da_fase_referenciada","status":422,"titulo":"A etapa que acontece na fase removida \xe9 referenciada pela classifica\xe7\xe3o ou por um crit\xe9rio de desempate"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.etapa_da_fase_referenciada","requisitos":[],"oQueAconteceu":["As etapas de uma fase saem junto com ela quando o cronograma \xe9 redefinido sem a\\nfase. Isso n\xe3o acontece se uma etapa dela \xe9 usada por configura\xe7\xe3o de fora da\\nfase: um crit\xe9rio de desempate pela maior nota da etapa ou uma regra de elimina\xe7\xe3o\\nda classifica\xe7\xe3o que cita a etapa. Remover a fase deixaria o desempate ou a\\nelimina\xe7\xe3o apontando para uma etapa que deixou de existir. A mensagem traz o\\nc\xf3digo e a ordem da fase e o nome da etapa.","A confer\xeancia \xe9 feita fase por fase, na ordem em que o processo as tem, e para na\\nprimeira recusa. Para uma fase removida, vem depois da recusa por documento\\nexigido que usa a fase como refer\xeancia\\n([`referenciada_por_exigencia_viva`](/erros/uniplus.selecao.fase_cronograma.referenciada_por_exigencia_viva))\\ne antes da recusa por formul\xe1rio respondido na fase\\n([`fase_referenciada_por_formulario`](/erros/uniplus.selecao.processo_seletivo.fase_referenciada_por_formulario)).\\nNada \xe9 gravado."],"comoResolver":["Reconfigure antes a classifica\xe7\xe3o: retire ou troque, nos crit\xe9rios de desempate\\n(`PUT .../criterios-desempate`) e nas regras de elimina\xe7\xe3o da classifica\xe7\xe3o, a\\nrefer\xeancia \xe0 etapa nomeada, e s\xf3 ent\xe3o repita a defini\xe7\xe3o do cronograma sem a fase.\\nSe a fase deve ficar, mantenha-a no cronograma."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);